            cnf.append(clause)
        return cnf

    def dpll(G):
        def solve(model):
            if not G:
                return True
            literal = next((l for l in range(1, len(G) + 1) if l not in model and -l not in model), None)
            if literal is None:
                return False

            pos_literal = literal
            neg_literal = -literal
            new_model_pos = {**model, pos_literal: True}
            new_model_neg = {**model, neg_literal: True}

            if solve(new_model_pos):
                return True
            if solve(new_model_neg):
                return True

            return False

        return solve({})

    def mls(G):
        n = len(G)
        if n == 1:
            return 0

        for i in range(n):
            for j in range(i + 1, n):
                if G[i][j-1] and G[j][i-1]:
                    return 2
        return 1

    def height(G):
        n = len(G)
