            return 0

        max_height = 0
        for i in range(n):
            for j in range(i + 1, n):
                if G[i][j-1] and G[j][i-1]:
                    max_height = max(max_height, height(G[:i]) + height(G[i+1:j]) + height(G[j+1:]))
